package com.example.hotel_service.shared.exception;
import org.springframework.http.*; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; import org.springframework.security.access.AccessDeniedException; import jakarta.validation.ConstraintViolationException; import java.time.Instant; import java.util.*;
@RestControllerAdvice public class GlobalExceptionHandler { @ExceptionHandler(ResourceNotFoundException.class) ResponseEntity<Map<String,Object>> notFound(ResourceNotFoundException e){return error(HttpStatus.NOT_FOUND,e.getMessage());} @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<Map<String,Object>> validation(MethodArgumentNotValidException e){Map<String,String> errors=new LinkedHashMap<>();e.getBindingResult().getFieldErrors().forEach(x->errors.put(x.getField(),x.getDefaultMessage()));Map<String,Object> body=base(HttpStatus.BAD_REQUEST,"Validation failed");body.put("errors",errors);return ResponseEntity.badRequest().body(body);} @ExceptionHandler({ConstraintViolationException.class,IllegalArgumentException.class}) ResponseEntity<Map<String,Object>> bad(RuntimeException e){return error(HttpStatus.BAD_REQUEST,"Invalid request");} @ExceptionHandler(AccessDeniedException.class) ResponseEntity<Map<String,Object>> forbidden(){return error(HttpStatus.FORBIDDEN,"Access denied");} @ExceptionHandler(Exception.class) ResponseEntity<Map<String,Object>> unexpected(Exception e){return error(HttpStatus.INTERNAL_SERVER_ERROR,"An unexpected error occurred");} private ResponseEntity<Map<String,Object>> error(HttpStatus s,String m){return ResponseEntity.status(s).body(base(s,m));} private Map<String,Object> base(HttpStatus s,String m){Map<String,Object>b=new LinkedHashMap<>();b.put("status",s.value());b.put("message",m);b.put("timestamp",Instant.now());return b;} }
